# Общие JS-хелперы — как в data_t.py. Сравнение с порогом — с допуском 1e-9
# от модуля порога; fx показывает число рядом с порогом с таким числом
# значащих цифр, чтобы округлённое значение лежало по ту же сторону порога,
# что и точное. OPT: необязательное поле — пустое даёт null, нечисловое — NaN.
# rd — округление дБ-величины до 1e-9 дБ перед сравнением: так сумма дБ,
# которая «ровно» равна порогу, не даёт вердикта «ниже на 1,2·10^-15 дБ».
V_JS = r'''
function gt(a,b){return a>b+Math.abs(b)*1e-9;}
function lt(a,b){return a<b-Math.abs(b)*1e-9;}
function ge(a,b){return a>=b-Math.abs(b)*1e-9;}
function le(a,b){return a<=b+Math.abs(b)*1e-9;}
function fe(x,p){var s=Number(x.toPrecision(p)),a=Math.abs(s);if(a===0||(a<1e7&&a>=1e-4))return fmt(x,p);var t=s.toExponential(p-1).replace(/(\.\d*?)0+e/,'$1e').replace('.e','e');return t.replace('e+','·10^').replace('e','·10^').replace('.',',');}
function fx(x,lim){if(Math.abs(x-lim)<=Math.abs(lim)*1e-9)return fe(x,4);for(var p=4;p<=12;p++){var r=Number(x.toPrecision(p));if((x<lim?lt(r,lim):gt(r,lim))&&r!==Number(lim.toPrecision(p)))return fe(x,p);}return fe(x,12);}
function OPT(id){var el=$(id);if(!el)return null;if(String(el.value).trim()==='')return null;return P(id);}
function sx(x,lim,u){var Pr=[[1e9,'Г'],[1e6,'М'],[1e3,'к'],[1,''],[1e-3,'м'],[1e-6,'мк'],[1e-9,'н'],[1e-12,'п']];for(var i=0;i<Pr.length-1;i++){if(Math.abs(x)>=Pr[i][0])break;}return fx(x/Pr[i][0],lim/Pr[i][0])+' '+Pr[i][1]+u;}
function sg(x){return x>0?'+':'';}
function rd(x){return Math.round(x*1e9)/1e9;}
// Малый зазор в дБ словами: иначе fmt вывел бы «1·10^-6».
function dbs(x){if(x!==0&&Math.abs(x)<1e-3)return (x<0?'−':'')+'меньше 0,001';return fmt(x);}
// Мощность в ваттах из дБм словами за пределами диапазона si: иначе вышли бы числа вроде 1·10^-30 Вт.
function pw(dbm){if(dbm<-120)return 'меньше 1 фВт';if(dbm>120)return 'больше 1 ГВт';return si(Math.pow(10,dbm/10)*1e-3,'Вт');}
function perms(a){if(a.length<=1)return [a.slice()];var r=[];for(var i=0;i<a.length;i++){var rest=a.slice(0,i).concat(a.slice(i+1));perms(rest).forEach(function(p){r.push([a[i]].concat(p));});}return r;}
'''

